CREATE TABLE product (id VARCHAR(64) PRIMARY KEY,tenant_id VARCHAR(64) NOT NULL,branch_id VARCHAR(64) NOT NULL,type VARCHAR(20) NOT NULL,title VARCHAR(160) NOT NULL,description TEXT NOT NULL,price_minor BIGINT NOT NULL,stock INT NOT NULL,course_id VARCHAR(64),lesson_units INT NOT NULL,published BOOLEAN NOT NULL,version INT NOT NULL DEFAULT 1,INDEX idx_product_branch(tenant_id,branch_id,published));
CREATE TABLE commerce_order (id VARCHAR(32) PRIMARY KEY,tenant_id VARCHAR(64) NOT NULL,branch_id VARCHAR(64) NOT NULL,user_id VARCHAR(64) NOT NULL,product_id VARCHAR(64) NOT NULL,student_id VARCHAR(64),course_id VARCHAR(64),product_type VARCHAR(20) NOT NULL,product_title VARCHAR(160) NOT NULL,unit_minor BIGINT NOT NULL,quantity INT NOT NULL,total_minor BIGINT NOT NULL,lesson_units INT NOT NULL,payment_status VARCHAR(24) NOT NULL,fulfillment_status VARCHAR(24) NOT NULL,idempotency_key VARCHAR(100) NOT NULL,transaction_id VARCHAR(100),prepay_id VARCHAR(100),tracking_number VARCHAR(160),fulfillment_method VARCHAR(20) NOT NULL DEFAULT 'PICKUP',recipient_name VARCHAR(80),recipient_phone VARCHAR(32),delivery_address VARCHAR(500),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,paid_at TIMESTAMP NULL,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_order_command(tenant_id,user_id,idempotency_key),UNIQUE KEY uk_order_transaction(transaction_id),INDEX idx_order_branch(tenant_id,branch_id,created_at));
CREATE TABLE commerce_refund (id VARCHAR(32) PRIMARY KEY,order_id VARCHAR(32) NOT NULL,tenant_id VARCHAR(64) NOT NULL,idempotency_key VARCHAR(100) NOT NULL,reason VARCHAR(500) NOT NULL,amount_minor BIGINT NOT NULL,status VARCHAR(32) NOT NULL,provider_refund_id VARCHAR(100),last_error VARCHAR(500),attempts INT NOT NULL DEFAULT 0,next_attempt_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_refund_order(order_id),UNIQUE KEY uk_refund_command(tenant_id,idempotency_key),INDEX idx_refund_reconcile(status,next_attempt_at));
CREATE TABLE commerce_aftersale (id VARCHAR(32) PRIMARY KEY,order_id VARCHAR(32) NOT NULL,user_id VARCHAR(64) NOT NULL,reason VARCHAR(2000) NOT NULL,status VARCHAR(24) NOT NULL,response VARCHAR(2000),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_aftersale_order(order_id));
CREATE TABLE commerce_reconciliation (id VARCHAR(32) PRIMARY KEY,order_id VARCHAR(32) NOT NULL,provider_status VARCHAR(32) NOT NULL,result VARCHAR(32) NOT NULL,checked_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_reconciliation_order(order_id,checked_at));
